// Run only these tests:  pnpm test:drift

import { describe, expect, it } from "vitest";
import { detectDrift } from "./detectDrift";

describe("detectDrift", () => {
  it("returns nothing when every edit was planned", () => {
    const intents = { alice: ["payments/vault.ts", "checkout/order.ts"] };
    const edits = { alice: ["payments/vault.ts", "checkout/order.ts"] };
    expect(detectDrift(intents, edits)).toEqual([]);
  });

  it("returns nothing when nobody has edited anything", () => {
    expect(detectDrift({ alice: ["payments/vault.ts"] }, {})).toEqual([]);
  });

  it("flags a file that was edited but not planned (the demo's cardCache.ts)", () => {
    const intents = { alice: ["payments/vault.ts", "checkout/order.ts"] };
    const edits = { alice: ["payments/vault.ts", "payments/cardCache.ts"] };

    const drift = detectDrift(intents, edits);

    expect(drift).toHaveLength(1);
    expect(drift[0]).toMatchObject({ id: "d1", participant: "alice", file: "payments/cardCache.ts" });
  });

  it("gives every drift a non-empty reason", () => {
    const drift = detectDrift({ alice: [] }, { alice: ["payments/cardCache.ts"] });
    expect(drift[0].reason.length).toBeGreaterThan(0);
  });

  it("checks each person against their OWN plan, not someone else's", () => {
    const intents = { alice: ["payments/vault.ts"], bob: ["account/user.ts"] };
    const edits = { alice: ["payments/vault.ts"], bob: ["payments/vault.ts"] };

    const drift = detectDrift(intents, edits);

    expect(drift).toHaveLength(1);
    expect(drift[0]).toMatchObject({ participant: "bob", file: "payments/vault.ts" });
  });

  it("numbers results d1, d2, d3 in the order of the edits", () => {
    const intents = { alice: [], bob: [] };
    const edits = { alice: ["a.ts", "b.ts"], bob: ["c.ts"] };

    expect(detectDrift(intents, edits).map((d) => [d.id, d.participant, d.file])).toEqual([
      ["d1", "alice", "a.ts"],
      ["d2", "alice", "b.ts"],
      ["d3", "bob", "c.ts"],
    ]);
  });

  it("does not flag anyone who never announced a plan", () => {
    const intents = { alice: ["payments/vault.ts"] };
    const edits = { sam: ["search/index.ts"] };
    expect(detectDrift(intents, edits)).toEqual([]);
  });

  // Edge case
  it("reports a file edited twice only once", () => {
    const intents = { alice: ["payments/vault.ts"] };
    const edits = { alice: ["payments/cardCache.ts", "payments/vault.ts", "payments/cardCache.ts"] };

    const drift = detectDrift(intents, edits);

    expect(drift.map((d) => d.file)).toEqual(["payments/cardCache.ts"]);
  });
});
